B.aP5=new A.e9("chief","Chief Ouru","village_chief",7,3,12,B.aFY,"eastGateOpen",B.aFy,"questDone:warchief",B.apt,!0,!1,!1,!1,B.KG,"mage","chief_ouru","chief_ouru_happy",null,null)
B.axE=s(["Hold still. This salve stings.","Another one from the east. The wounds are deep.","Drink first. Then tell me what you saw out there."],t.s)
B.aPj=new A.e9("healer","Healer Mira","village_healer",4,3,12,B.axE,null,null,null,null,!0,!1,!1,!0,null,"priest",null,null,"healer",null)
B.avc=s(["Are you a warrior? Mum says orcs eat children.","I drew an orc. It is very ugly.","Uncle says the orcs will come back this year."],t.s)
B.aPh=new A.e9("child","Tali","village_family",9,3,12,B.avc,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"child",null)
B.any=s(["The deer ran east. Strange for deer.","Watch the tree line when you go out.","My bow is strung. Always."],t.s)
B.aP8=new A.e9("hunter","Hunter Dahk","village",20,15,12,B.any,null,null,null,null,!0,!1,!1,!1,null,"archer",null,null,"hunter",null)
B.av3=s(["I remember when the east was only forest.","Fire keeps the bad things away. Mostly."],t.s)
B.aP7=new A.e9("elder","Elder Sohn","village",31,34,12,B.av3,null,null,null,null,!0,!1,!1,!1,null,"mage",null,null,"marl","sohn_scene")
B.aC6=s(["Sit, sit! Best salve in the world, this.","Two more weeks and I am back out there."],t.s)
B.aPo=new A.e9("ansa","Ansa","village",27,23,22,B.aC6,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"healer","ansa_scene")
B.as6=s(["The gate is closed for now.","We doubled the watch since the smoke rose.","Nothing comes through here without the chief."],t.s)
B.ax8=s(["The chief opened the way. Watch yourself out there."],t.s)
B.aOZ=new A.e9("guard","Guard Brek","village",66,35,12,B.as6,"eastGateOpen",B.ax8,null,null,!0,!1,!1,!1,null,"sword",null,null,"child","brek_scene")
B.aFl=s(["I came back from the east. Do not ask.","Those were not hunters' fires out there.","Let me rest. My arm still bleeds."],t.s)
B.aP6=new A.e9("scout","Scout Ilun","village",24,20,12,B.aFl,null,null,null,null,!0,!1,!1,!1,null,"archer",null,null,"scout",null)
B.aiY=s(["Courier Pell, fastest legs in the village!","Letters, parcels, secrets. Well. Letters."],t.s)
B.aOX=new A.e9("pell","Courier Pell","village",63,37,15,B.aiY,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"pell",null)
B.awC=s(["I will shape tools here once my bench is set.","Bring me hide and bone and I will work them."],t.s)
B.aP1=new A.e9("crafter","Tarn","village",52,33,12,B.awC,null,null,null,null,!1,!1,!1,!1,null,"adventurer",null,null,null,null)
B.aqt=s(["Fair prices, friend.","Have a look."],t.s)
