B.b57=new A.qV(0.21,0.5,0.55)
B.aYf=new A.nR(B.p3,B.h9,B.b57,1)
B.aY8=new A.vK("orc_warchief.png",0.894)
B.aYb=new A.nR(B.aY8,B.h9,null,1)
B.fg=new A.F(B.aQK,[B.aYg,B.aYd,B.aYe,B.aYh,B.aYc,B.aYa,B.aY9,B.aYi,B.aYf,B.aYb],A.a_("F<h,nR>"))
